111	 * Name: _get_val, set_val, _add_val
112	 *
113	 * Description:
114	 *   These functions are used when relocating an instruction because we can
115	 *   not assume the instruction is word-aligned.
116	 *
117	 ****************************************************************************/
118	
119	static uint32_t _get_val(uint16_t *addr)
120	{
121	  uint32_t ret;
122	  ret = *addr | (*(addr + 1)) << 16;
123	  return ret;
124	}
125	
126	static void _set_val(uint16_t *addr, uint32_t val)
127	{
128	  *addr       = (val & 0xffff);
129	  *(addr + 1) = (val >> 16);
130	
131	  /* NOTE: Ensure relocation before execution */
132	
133	  UP_ISB();
134	}
135	
136	static void _add_val(uint16_t *addr, uint32_t val)
137	{
138	  uint32_t cur = _get_val(addr);
139	  _set_val(addr, cur + val);
140	}
141	
142	/****************************************************************************
143	 * Name: _calc_imm
144	 *
145	 * Description:
146	 *   Given offset and obtain imm_hi (20bit) and imm_lo (12bit)
147	 *
148	 * Input Parameters:
149	 *   offset - signed 32bit
150	 *   imm_hi - signed 20bit
151	 *   imm_lo - signed 12bit
152	 *
153	 * Returned Value:
154	 *   none
155	 *
156	 ****************************************************************************/
157	
158	static void _calc_imm(long offset, long *imm_hi, long *imm_lo)
159	{
160	  long lo;
161	  long hi = offset / 4096;
162	  long r  = offset % 4096;
163	
164	  if (2047 < r)
165	    {
166	      hi++;
167	    }
168	  else if (r < -2048)
169	    {
170	      hi--;
171	    }
172	
173	  lo = offset - (hi * 4096);
174	
175	  binfo("offset=%ld: hi=%ld lo=%ld\n",
176	        offset, hi, lo);
177	
178	  ASSERT(-2048 <= lo && lo <= 2047);
179	
180	  *imm_lo = lo;
181	  *imm_hi = hi;
182	}
183	
184	/****************************************************************************
185	 * Name: _add_hi20
186	 *
187	 * Description:
188	 *   Add PCREL_HI20 relocation offset to the LUT. When a PCREL_LO12_I/_S is
189	 *   encountered, the corresponding PCREL_HI20 value can be found from it.
190	 *
191	 * Input Parameters:
192	 *   arch_data   - Where the PCREL_HI20 relocations are listed.
193	 *   hi20_rel    - The PCREL_HI20 relocation entry.
194	 *   hi20_offset - The corresponding offset value.
195	 *
196	 * Returned Value:
197	 *   None.
198	 *
199	 ****************************************************************************/
200	
201	static void _add_hi20(void *arch_data, uintptr_t hi20_rel,
202	                      uintptr_t hi20_offset)
203	{
204	  arch_elfdata_t *data = (arch_elfdata_t *)arch_data;
205	  int i;
206	
207	  /* Try to find a free slot from the list */
208	
209	  for (i = 0; i < ARCH_ELF_RELCNT; i++)
210	    {
211	      struct hi20_rels_s *hi20 = &data->hi20_rels[i];
212	
213	      if (hi20->hi20_rel == 0)
214	        {
215	          hi20->hi20_rel = hi20_rel;
216	          hi20->hi20_offset = hi20_offset;
217	          break;
218	        }
219	    }
220	}
221	
222	/****************************************************************************
223	 * Name: _find_hi20
224	 *
225	 * Description:
226	 *   Find PCREL_HI20 relocation offset from the LUT. When a PCREL_LO12_I/_S
227	 *   is encountered, the corresponding PCREL_HI20 value is needed to do the
228	 *   relocation.
229	 *
230	 * Input Parameters:
231	 *   arch_data   - Where the PCREL_HI20 relocations are listed.
232	 *   hi20_rel    - The PCREL_HI20 relocation entry.
233	 *
234	 * Returned Value:
235	 *   The corresponding hi20_offset value.
236	 *
237	 ****************************************************************************/
238	
239	static uintptr_t _find_hi20(void *arch_data, uintptr_t hi20_rel)
240	{
241	  arch_elfdata_t *data = (arch_elfdata_t *)arch_data;
242	  int i;
243	
244	  /* Try to find the hi20 value from the list */
245	
246	  for (i = 0; i < ARCH_ELF_RELCNT; i++)
247	    {
248	      struct hi20_rels_s *hi20 = &data->hi20_rels[i];
249	
250	      if (hi20->hi20_rel == hi20_rel)
251	        {
252	          /* Found it, we can clear the entry now */
253	
254	          hi20->hi20_rel = 0;
255	          return hi20->hi20_offset;
256	        }
257	    }
258	
259	  return 0;
260	}
261	
262	/****************************************************************************
263	 * Name: _valid_hi20_imm
264	 *
265	 * Description:
266	 *   Check that any XX_HI20 relocation has a valid upper 20-bit immediate.
267	 *   Note that this test is not necessary for RV32 targets, the problem is
268	 *   related to RV64 sign extension.
269	 *
270	 * Input Parameters:
271	 *   imm_hi - The upper immediate value.
272	 *
273	 * Returned Value:
274	 *   true if imm_hi is valid; false otherwise
275	 *
276	 ****************************************************************************/
277	
278	#ifdef CONFIG_ARCH_64BIT
279	static inline bool _valid_hi20_imm(long imm_hi)
280	{
281	  /* 32-bit sign extend imm_hi and compare with the original value */
282	
283	  long hi   = imm_hi & ((1 << 20) - 1);        /* 32-bit signed value */
284	  long sign = -((imm_hi >> 19) & 1);           /* 32-bit sign value */
285	  hi        = ((hi << 12) | sign << 32) >> 12; /* 32-bit sign extend */
286	
287	  /* If the values do not match, the immediate is invalid */
288	
289	  return imm_hi == hi;
290	}
291	#else
292	#  define _valid_hi20_imm(imm_hi) 1
293	#endif
