295	/****************************************************************************
296	 * Public Functions
297	 ****************************************************************************/
298	
299	/****************************************************************************
300	 * Name: up_checkarch
301	 *
302	 * Description:
303	 *   Given the ELF header in 'hdr', verify that the ELF file is appropriate
304	 *   for the current, configured architecture.  Every architecture that uses
305	 *   the ELF loader must provide this function.
306	 *
307	 * Input Parameters:
308	 *   hdr - The ELF header read from the ELF file.
309	 *
310	 * Returned Value:
311	 *   True if the architecture supports this ELF file.
312	 *
313	 ****************************************************************************/
314	
315	bool up_checkarch(const Elf_Ehdr *ehdr)
316	{
317	  /* Make sure it's an RISCV executable */
318	
319	  if (ehdr->e_machine != EM_RISCV)
320	    {
321	      berr("ERROR: Not for RISCV: e_machine=%04x\n", ehdr->e_machine);
322	      return false;
323	    }
324	
325	  /* Make sure that current objects are supported */
326	
327	  if (ehdr->e_ident[EI_CLASS] != ELF_CLASS)
328	    {
329	      berr("ERROR: Need " ARCH_ELF_TYP_STR "-bit "
330	           "objects: e_ident[EI_CLASS]=%02x\n",
331	           ehdr->e_ident[EI_CLASS]);
332	      return false;
333	    }
334	
335	  /* Verify endian-ness */
336	
337	#ifdef CONFIG_ENDIAN_BIG
338	  if (ehdr->e_ident[EI_DATA] != ELFDATA2MSB)
339	#else
340	  if (ehdr->e_ident[EI_DATA] != ELFDATA2LSB)
341	#endif
342	    {
343	      berr("ERROR: Wrong endian-ness: e_ident[EI_DATA]=%02x\n",
344	           ehdr->e_ident[EI_DATA]);
345	      return false;
346	    }
347	
348	  /* Make sure the entry point address is properly aligned */
349	
350	  if ((ehdr->e_entry & 1) != 0)
351	    {
352	      berr("ERROR: Entry point is not properly aligned: %" PRIxPTR "\n",
353	           (uintptr_t)ehdr->e_entry);
354	    }
355	
356	  /* TODO:  Check ABI here. */
357	
358	  return true;
359	}
360	
361	/****************************************************************************
362	 * Name: up_relocate and up_relocateadd
363	 *
364	 * Description:
365	 *   Perform an architecture-specific ELF relocation.  Every architecture
366	 *   that uses the ELF loader must provide this function.
367	 *
368	 * Input Parameters:
369	 *   rel - The relocation type
370	 *   sym - The ELF symbol structure containing the fully resolved value.
371	 *         There are a few relocation types for a few architectures that do
372	 *         not require symbol information.  For those, this value will be
373	 *         NULL.  Implementations of these functions must be able to handle
374	 *         that case.
375	 *   addr - The address that requires the relocation.
376	 *
377	 * Returned Value:
378	 *   Zero (OK) if the relocation was successful.  Otherwise, a negated errno
379	 *   value indicating the cause of the relocation failure.
380	 *
381	 ****************************************************************************/
382	
383	int up_relocate(const Elf_Rel *rel, const Elf_Sym *sym, uintptr_t addr,
384	                void *arch_data)
385	{
386	  berr("Not implemented\n");
387	  return -ENOSYS;
388	}
389	
390	int up_relocateadd(const Elf_Rela *rel, const Elf_Sym *sym,
391	                   uintptr_t addr, void *arch_data)
392	{
393	  long offset;
394	  unsigned int relotype;
395	
396	  /* All relocations depend upon having valid symbol information */
397	
398	  relotype = ELF_R_TYPE(rel->r_info);
399	
400	  if (relotype == R_RISCV_RELAX)
401	    {
402	      /* NOTE: RELAX has no symbol, so just return */
403	
404	      binfo("%s at %08" PRIxPTR " [%08" PRIx32 "]\n",
405	            _get_rname(relotype),
406	            addr, _get_val((uint16_t *)addr));
407	
408	      return OK;
409	    }
410	
411	  if (sym == NULL && relotype != R_RISCV_NONE)
412	    {
413	      return -EINVAL;
414	    }
415	
416	  /* Do relocation based on relocation type */
417	
418	  switch (relotype)
419	    {
420	      case R_RISCV_32:
421	      case R_RISCV_64:
422	        {
423	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
424	                "to sym=%p st_value=%" PRIxPTR "\n",
425	                _get_rname(relotype),
426	                addr, _get_val((uint16_t *)addr),
427	                sym, (uintptr_t)sym->st_value);
428	
429	          _set_val((uint16_t *)addr,
430	                   (uint32_t)(sym->st_value + rel->r_addend));
431	        }
432	        break;
433	
434	      case R_RISCV_PCREL_LO12_I:
435	        {
436	          long imm_hi;
437	          long imm_lo;
438	
439	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
440	                "to sym=%p st_value=%" PRIxPTR "\n",
441	                _get_rname(relotype),
442	                addr, _get_val((uint16_t *)addr),
443	                sym, (uintptr_t)sym->st_value);
444	
445	          offset = _find_hi20(arch_data, sym->st_value);
446	
447	          /* Adjust imm for MV(ADDI) / JR (JALR) : I-type */
448	
449	          _calc_imm(offset, &imm_hi, &imm_lo);
450	
451	          _add_val((uint16_t *)addr, (int32_t)imm_lo << 20);
452	        }
453	        break;
454	
455	      case R_RISCV_PCREL_LO12_S:
456	        {
457	          uint32_t val;
458	          long imm_hi;
459	          long imm_lo;
460	
461	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
462	                "to sym=%p st_value=%" PRIxPTR "\n",
463	                _get_rname(relotype),
464	                addr, _get_val((uint16_t *)addr),
465	                sym, (uintptr_t)sym->st_value);
466	
467	          offset = _find_hi20(arch_data, sym->st_value);
468	
469	          /* Adjust imm for SW : S-type */
470	
471	          _calc_imm(offset, &imm_hi, &imm_lo);
472	
473	          val = (((int32_t)imm_lo >> 5) << 25) +
474	                (((int32_t)imm_lo & 0x1f) << 7);
475	
476	          binfo("imm_lo=%ld (%lx), val=%" PRIx32 "\n", imm_lo, imm_lo, val);
477	
478	          _add_val((uint16_t *)addr, val);
479	        }
480	        break;
481	
482	      case R_RISCV_PCREL_HI20:
483	        {
484	          uint32_t insn;
485	          long imm_hi;
486	          long imm_lo;
487	
488	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
489	                "to sym=%p st_value=%" PRIxPTR "\n",
490	                _get_rname(relotype),
491	                addr, _get_val((uint16_t *)addr),
492	                sym, (uintptr_t)sym->st_value);
493	
494	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
495	
496	          insn = _get_val((uint16_t *)addr);
497	          ASSERT(OPCODE_AUIPC == (insn & RVI_OPCODE_MASK));
498	
499	          _calc_imm(offset, &imm_hi, &imm_lo);
500	
501	          if (!_valid_hi20_imm(imm_hi))
502	            {
503	              berr("ERROR: %s at %08" PRIxPTR " bad:%08" PRIxPTR "\n",
504	                   _get_rname(relotype), addr, (uintptr_t)imm_hi << 12);
505	
506	              return -EINVAL;
507	            }
508	
509	          /* Adjust auipc (add upper immediate to pc) : 20bit */
510	
511	          _add_val((uint16_t *)addr, imm_hi << 12);
512	
513	          /* Add the hi20 value to the cache */
514	
515	          _add_hi20(arch_data, addr, offset);
516	        }
517	        break;
518	
519	      case R_RISCV_CALL:
520	      case R_RISCV_CALL_PLT:
521	        {
522	          long imm_hi;
523	          long imm_lo;
524	
525	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
526	                "to sym=%p st_value=%" PRIxPTR "\n",
527	                _get_rname(relotype),
528	                addr, _get_val((uint16_t *)addr),
529	                sym, (uintptr_t)sym->st_value);
530	
531	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
532	
533	          _calc_imm(offset, &imm_hi, &imm_lo);
534	
535	          if (!_valid_hi20_imm(imm_hi))
536	            {
537	              berr("ERROR: %s at %08" PRIxPTR " bad:%08" PRIxPTR "\n",
538	                   _get_rname(relotype), addr, (uintptr_t)imm_hi << 12);
539	
540	              return -EINVAL;
541	            }
542	
543	          /* Adjust auipc (add upper immediate to pc) : 20bit */
544	
545	          _add_val((uint16_t *)addr, imm_hi << 12);
546	
547	          /* Adjust imm for CALL (JALR) : I-type */
548	
549	          _add_val((uint16_t *)(addr + 4), (int32_t)imm_lo << 20);
550	        }
551	        break;
552	
553	      case R_RISCV_BRANCH:
554	        {
555	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
556	                "to sym=%p st_value=%" PRIxPTR "\n",
557	                _get_rname(relotype),
558	                addr, _get_val((uint16_t *)addr),
559	                sym, (uintptr_t)sym->st_value);
560	
561	          /* P.23 Conditinal Branches : B type (imm=12bit) */
562	
563	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
564	          uint32_t val = _get_val((uint16_t *)addr) & 0xfe000f80;
565	
566	          /* NOTE: we assume that a compiler adds an immediate value */
567	
568	          ASSERT(offset && val);
569	
570	          binfo("offset for Bx=%ld (0x%lx) (val=0x%08" PRIx32 ") "
571	                "already set!\n",
572	                offset, offset, val);
573	        }
574	        break;
575	
576	      case R_RISCV_JAL:
577	        {
578	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
579	                "to sym=%p st_value=%" PRIxPTR "\n",
580	                _get_rname(relotype),
581	                addr, _get_val((uint16_t *)addr),
582	                sym, (uintptr_t)sym->st_value);
583	
584	          /* P.21 Unconditinal Jumps : UJ type (imm=20bit) */
585	
586	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
587	          uint32_t val = _get_val((uint16_t *)addr) & 0xfffff000;
588	
589	          ASSERT(offset && val);
590	
591	          /* NOTE: we assume that a compiler adds an immediate value */
592	
593	          binfo("offset for JAL=%ld (0x%lx) (val=0x%08" PRIx32 ") "
594	                "already set!\n",
595	                offset, offset, val);
596	        }
597	        break;
598	
599	      case R_RISCV_HI20:
600	        {
601	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
602	                "to sym=%p st_value=%" PRIxPTR "\n",
603	                _get_rname(relotype),
604	                addr, _get_val((uint16_t *)addr),
605	                sym, (uintptr_t)sym->st_value);
606	
607	          /* P.19 LUI */
608	
609	          offset = (long)sym->st_value + (long)rel->r_addend;
610	          uint32_t insn = _get_val((uint16_t *)addr);
611	
612	          ASSERT(OPCODE_LUI == (insn & RVI_OPCODE_MASK));
613	
614	          long imm_hi;
615	          long imm_lo;
616	          _calc_imm(offset, &imm_hi, &imm_lo);
617	
618	          if (!_valid_hi20_imm(imm_hi))
619	            {
620	              berr("ERROR: %s at %08" PRIxPTR " bad:%08" PRIxPTR "\n",
621	                   _get_rname(relotype), addr, (uintptr_t)imm_hi << 12);
622	
623	              return -EINVAL;
624	            }
625	
626	          insn = (insn & 0x00000fff) | (imm_hi << 12);
627	
628	          _set_val((uint16_t *)addr, insn);
629	        }
630	        break;
631	
632	      case R_RISCV_LO12_I:
633	        {
634	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
635	                "to sym=%p st_value=%" PRIxPTR "\n",
636	                _get_rname(relotype),
637	                addr, _get_val((uint16_t *)addr),
638	                sym, (uintptr_t)sym->st_value);
639	
640	          /* ADDI, FLW, LD, ... : I-type */
641	
642	          offset = (long)sym->st_value + (long)rel->r_addend;
643	          uint32_t insn = _get_val((uint16_t *)addr);
644	
645	          long imm_hi;
646	          long imm_lo;
647	          _calc_imm(offset, &imm_hi, &imm_lo);
648	          insn = (insn & 0x000fffff) | (imm_lo << 20);
649	
650	          _set_val((uint16_t *)addr, insn);
651	        }
652	        break;
653	
654	      case R_RISCV_LO12_S:
655	        {
656	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
657	                "to sym=%p st_value=%" PRIxPTR "\n",
658	                _get_rname(relotype),
659	                addr, _get_val((uint16_t *)addr),
660	                sym, (uintptr_t)sym->st_value);
661	
662	          /* SW : S-type.
663	           * not merge with R_RISCV_HI20 since the compiler
664	           * may not generates these two instructions continuously.
665	           */
666	
667	          offset = (long)sym->st_value + (long)rel->r_addend;
668	
669	          long imm_hi;
670	          long imm_lo;
671	          _calc_imm(offset, &imm_hi, &imm_lo);
672	
673	          uint32_t val =
674	              (((int32_t)imm_lo >> 5) << 25) +
675	              (((int32_t)imm_lo & 0x1f) << 7);
676	
677	          binfo("imm_lo=%ld (%lx), val=%" PRIx32 "\n", imm_lo, imm_lo, val);
678	
679	          _add_val((uint16_t *)addr, val);
680	        }
681	        break;
682	
683	      case R_RISCV_RVC_JUMP:
684	        {
685	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
686	                "to sym=%p st_value=%" PRIxPTR "\n",
687	                _get_rname(relotype),
688	                addr, _get_val((uint16_t *)addr),
689	                sym, (uintptr_t)sym->st_value);
690	
691	          /* P.111 Table 16.6 : Instruction listings for RVC */
692	
693	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
694	          ASSERT(-2048 <= offset && offset <= 2047);
695	
696	          uint16_t val = (*(uint16_t *)addr) & 0x1ffc;
697	
698	          binfo("offset for C.J=%ld (0x%lx) (val=0x%04x) already set!\n",
699	                offset, offset, val);
700	        }
701	        break;
702	
703	      case R_RISCV_RVC_BRANCH:
704	        {
705	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
706	                "to sym=%p st_value=%" PRIxPTR "\n",
707	                _get_rname(relotype),
708	                addr, _get_val((uint16_t *)addr),
709	                sym, (uintptr_t)sym->st_value);
710	
711	          /* P.111 Table 16.6 : Instruction listings for RVC */
712	
713	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
714	          ASSERT(-256 <= offset && offset <= 255);
715	
716	          uint16_t val = (*(uint16_t *)addr) & 0x1c7c;
717	
718	          /* NOTE: we assume that a compiler adds an immediate value */
719	
720	          ASSERT(offset && val);
721	
722	          binfo("offset for C.Bx=%ld (0x%lx) (val=0x%04x) already set!\n",
723	                offset, offset, val);
724	        }
725	        break;
726	      case R_RISCV_32_PCREL:
727	        {
728	          /* P.29 https://github.com/riscv-non-isa/riscv-elf-psabi-doc */
729	
730	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
731	                "to sym=%p st_value=%" PRIxPTR "\n",
732	                _get_rname(relotype),
733	                addr, _get_val((uint16_t *)addr),
734	                sym, (uintptr_t)sym->st_value);
735	
736	          addr = (long)sym->st_value + (long)rel->r_addend - (long)addr;
737	        }
738	        break;
739	      case R_RISCV_ADD32:
740	        {
741	          *(uint32_t *)addr += (uint32_t)(sym->st_value + rel->r_addend);
742	        }
743	        break;
744	      case R_RISCV_ADD64:
745	        {
746	          *(uint64_t *)addr += (uint64_t)(sym->st_value + rel->r_addend);
747	        }
748	        break;
749	      case R_RISCV_SUB16:
750	        {
751	          *(uint16_t *)addr -= (uint16_t)(sym->st_value + rel->r_addend);
752	        }
753	        break;
754	      case R_RISCV_SUB32:
755	        {
